  function listenToMyNotifications(tenantId, uid, onData, onError) {
    const q = query(
      collection(db, COLLECTIONS.notifications()),
      where("tenantId", "==", tenantId),
      where("userId", "==", uid),
      orderBy("createdAt", "desc"),
      limit(50)
    );
    return onSnapshot(
      q,
      (snap) => onData(snap.docs.map((d) => d.data())),
      onError
    );
  }

